    col_counts = [sum(grid[r][c] == 2 for r in range(h)) for c in range(w)]
    horizontal_rails = [r for r, n in enumerate(row_counts) if n >= w / 2]
    vertical_rails = [c for c, n in enumerate(col_counts) if n >= h / 2]

    horizontal = max(row_counts, default=0) > max(col_counts, default=0)
    rails = horizontal_rails if horizontal else vertical_rails

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[r + dr][c + dc] == 3
                for dr in (-1, 0, 1)
                for dc in (-1, 0, 1)
                if (dr, dc) != (0, 0)
            ):
                centers.append((r, c))

