def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    row_counts = [sum(v == 2 for v in grid[r]) for r in range(h)]
    col_counts = [sum(grid[r][c] == 2 for r in range(h)) for c in range(w)]

    # The long, nearly continuous 2-lines are the parallel rails.
    horizontal = max(row_counts, default=0) > max(col_counts, default=0)
    if horizontal:
        rails = [r for r, n in enumerate(row_counts) if n >= 0.75 * w]
    else:
        rails = [c for c, n in enumerate(col_counts) if n >= 0.75 * h]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[r + dr][c + dc] == 3
                for dr in (-1, 0, 1)
                for dc in (-1, 0, 1)
                if (dr, dc) != (0, 0)
            ):
                centers.append((r, c))

    for r, c in centers:
        if horizontal:
            if r not in rails:
                continue
            # Beam runs perpendicular to the horizontal rails.
            for rr in range(h):
                if grid[rr][c] == 0:
                    out[rr][c] = 1
            crossings = [(rail, c) for rail in rails if rail != r]
        else:
            if c not in rails:
                continue
            # Beam runs perpendicular to the vertical rails.
            for cc in range(w):
                if grid[r][cc] == 0:
                    out[r][cc] = 1
            crossings = [(r, rail) for rail in rails if rail != c]

        # At each rail crossing, flare the beam into a 3x3 patch.
        # Keep the crossing cell itself and any original 3s unchanged.
        for cr, cc in crossings:
            for rr in range(cr - 1, cr + 2):
                for x in range(cc - 1, cc + 2):
                    if (0 <= rr < h and 0 <= x < w
                            and (rr, x) != (cr, cc)
                            and grid[rr][x] != 3):
                        out[rr][x] = 1

    return out
